import React, { createContext, useContext, useMemo, useState } from 'react';
import { initialReports } from './reportData';

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [reports, setReports] = useState(initialReports);
  const [toast, setToast] = useState('');
  const notify = message => {
    setToast(message);
    window.setTimeout(() => setToast(''), 2600);
  };
  const updateReport = (id, changes) => setReports(current => current.map(report => report.id === id ? { ...report, ...changes } : report));
  const value = useMemo(() => ({ reports, updateReport, notify }), [reports]);
  return <AppContext.Provider value={value}>{children}{toast && <div className="toast">✓ &nbsp;{toast}</div>}</AppContext.Provider>;
}

export function useApp() {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
}
